/* No animation dependency or frame loop: dimensional branding, light trails, and deliberate reveals. */
function bindAttention(){
 document.querySelectorAll('.brand').forEach(brand=>{if(!brand.querySelector('.brand-word')){const icon=brand.querySelector('img');brand.setAttribute('aria-label','Camino home');brand.replaceChildren();if(icon){icon.classList.add('brand-cube');brand.append(icon)}const word=document.createElement('span');word.className='brand-word';word.setAttribute('aria-hidden','true');for(const [i,letter]of [...'camino.'].entries()){const span=document.createElement('span');span.className='brand-letter';span.style.setProperty('--letter',i);span.textContent=letter;word.append(span)}brand.append(word)}brand.onpointermove=e=>{if(journeyReduced()||e.pointerType==='touch')return;const r=brand.getBoundingClientRect();brand.style.setProperty('--brand-turn',((e.clientX-r.left)/Math.max(1,r.width)-.5)*14+'deg');brand.style.setProperty('--brand-lift',((e.clientY-r.top)/Math.max(1,r.height)-.5)*-6+'deg')};brand.onpointerleave=()=>{brand.style.setProperty('--brand-turn','0deg');brand.style.setProperty('--brand-lift','0deg')}});
 const headline=document.querySelector('.journey-hero h1');if(headline&&!headline.querySelector('.kinetic-line'))headline.innerHTML='<span class="kinetic-line"><span>Your future</span></span><span class="kinetic-line"><em>starts here.</em></span>';
 const hero=document.querySelector('.journey-hero');if(hero){hero.onpointermove=e=>{if(journeyReduced()||e.pointerType==='touch')return;const r=hero.getBoundingClientRect();hero.style.setProperty('--headline-x',((e.clientX-r.left)/Math.max(1,r.width)-.5)*5+'px')};hero.onpointerleave=()=>hero.style.setProperty('--headline-x','0px')}
}
function installAttention(){
 const original=journeyBranchVisual;journeyBranchVisual=()=>{let visual=original();const paths=['M400 520V405Q400 360 400 335C400 265 160 345 160 198','M400 520V405Q400 360 400 335V136','M400 520V405Q400 360 400 335C400 265 640 345 640 198'];const ridges=`<g class="route-depth" aria-hidden="true">${paths.map((p,i)=>`<path d="${p}" class="route-depth-${i}"/>`).join('')}</g><g class="route-step-lights">${Array.from({length:7},(_,i)=>`<path d="M${370-i*2} ${508-i*19}l30 -13 ${30+i*2} 13 -30 13Z" style="--rung:${i}"/>`).join('')}</g>`;visual=visual.replace('<g class="direction-contours">',ridges+'<g class="direction-contours">');if(!journeyReduced()){const dots=paths.map((p,i)=>`<circle class="motion-traveler traveler-${i}" r="${i===1?4:3}" fill="${['#a4efda','#baadff','#f19dd8'][i]}"><animateMotion dur="${6+i}s" begin="${i*.8}s" repeatCount="3" path="${p}"/></circle>`).join('');visual=visual.replace('</svg><button class="direction-stop',dots+'</svg><button class="direction-stop')}return visual};
 const originalBind=bind;bind=()=>{originalBind();bindAttention()};
}
